using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;

namespace RhinoVSBridge
{
    /// <summary>
    /// Locates the stubs generated by the Rhino 8 ScriptEditor, and writes Visual Studio PTVS search paths.
    /// Never modifies the Rhino Python installation or copies binaries to a Python environment.
    /// </summary>
    internal static class IntelliSensePaths
    {
        internal const string CompatibilityDirectory = @".rhino-vs-bridge\typings";
        private const string GeneratedMarker = "# Generated by Rhino VS Bridge. Project-local typing only; never executed by Rhino.";
        private const string ScriptContextStub = GeneratedMarker + "\r\n" +
            "from typing import Any, MutableMapping\r\n" +
            "import Rhino\r\n\r\n" +
            "doc: Rhino.RhinoDoc\r\n" +
            "id: int\r\n" +
            "sticky: MutableMapping[Any, Any]\r\n\r\n" +
            "def escape_test(throw_exception: bool = ..., reset: bool = ...) -> None: ...\r\n" +
            "def errorhandler() -> None: ...\r\n" +
            "def localize(text: str) -> Any: ...\r\n";

        internal sealed class ConfigurationResult
        {
            public int AddedPaths { get; set; }
            public bool CompatibilityStubWritten { get; set; }
            public string CompatibilityStubPath { get; set; } = string.Empty;
        }

        public static IReadOnlyList<string> Discover()
        {
            var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
            var python = Path.Combine(home, ".rhinocode", "py39-rh8");
            var result = new List<string>();
            var stubs = Path.Combine(python, "site-stubs");
            if (Directory.Exists(stubs))
            {
                // Pylance needs the directory that directly contains Rhino/__init__.pyi.
                // The parent site-stubs folder is not importable and may contain several versions.
                var generated = Directory.GetDirectories(stubs, "rhino3d-*")
                    .Where(path => File.Exists(Path.Combine(path, "Rhino", "__init__.pyi")))
                    .OrderByDescending(GetStubVersion)
                    .ThenByDescending(Directory.GetLastWriteTimeUtc)
                    .FirstOrDefault();
                if (generated != null) result.Add(generated);
            }

            foreach (var folder in new[] { "site-rhinopython", "site-interop" })
            {
                var path = Path.Combine(python, folder);
                if (Directory.Exists(path))
                {
                    result.Add(path);
                    // If rhinoscriptsyntax resides one or two levels lower, include its parent.
                    foreach (var child in Directory.GetDirectories(path))
                    {
                        if (ContainsRhinoScriptSyntax(child)) result.Add(child);
                    }
                }
            }

            return result.Where(Directory.Exists)
                .Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static Version GetStubVersion(string path)
        {
            var name = Path.GetFileName(path);
            var value = name.StartsWith("rhino3d-", StringComparison.OrdinalIgnoreCase)
                ? name.Substring("rhino3d-".Length) : string.Empty;
            return Version.TryParse(value, out var version) ? version : new Version(0, 0);
        }

        private static bool ContainsRhinoScriptSyntax(string folder)
        {
            return Directory.Exists(Path.Combine(folder, "rhinoscriptsyntax")) ||
                   File.Exists(Path.Combine(folder, "rhinoscriptsyntax.py"));
        }

        public static ConfigurationResult ConfigurePythonProject(string projectFile, IReadOnlyList<string> paths)
        {
            if (!string.Equals(Path.GetExtension(projectFile), ".pyproj", StringComparison.OrdinalIgnoreCase))
                throw new ArgumentException("Expected a Visual Studio Python project (*.pyproj).", nameof(projectFile));
            if (!File.Exists(projectFile)) throw new FileNotFoundException("Python project missing.", projectFile);

            var stubPath = EnsureCompatibilityStubs(projectFile);
            var projectPaths = new[] { CompatibilityDirectory }.Concat(paths).ToList();
            return new ConfigurationResult
            {
                AddedPaths = AddToPythonProject(projectFile, projectPaths),
                CompatibilityStubWritten = stubPath.Written,
                CompatibilityStubPath = stubPath.Path
            };
        }

        private static (string Path, bool Written) EnsureCompatibilityStubs(string projectFile)
        {
            var projectDirectory = Path.GetDirectoryName(Path.GetFullPath(projectFile))
                ?? throw new InvalidDataException("Python project has no directory.");
            var typingDirectory = Path.Combine(projectDirectory, CompatibilityDirectory);
            var stubPath = Path.Combine(typingDirectory, "scriptcontext.pyi");
            Directory.CreateDirectory(typingDirectory);
            if (File.Exists(stubPath))
            {
                var existing = File.ReadAllText(stubPath);
                if (!existing.StartsWith(GeneratedMarker, StringComparison.Ordinal))
                    return (stubPath, false);
                if (string.Equals(existing, ScriptContextStub, StringComparison.Ordinal))
                    return (stubPath, false);
            }
            File.WriteAllText(stubPath, ScriptContextStub);
            return (stubPath, true);
        }

        /// <returns>The number of newly added paths.</returns>
        public static int AddToPythonProject(string projectFile, IReadOnlyList<string> paths)
        {
            if (!string.Equals(Path.GetExtension(projectFile), ".pyproj", StringComparison.OrdinalIgnoreCase))
                throw new ArgumentException("Expected a Visual Studio Python project (*.pyproj).", nameof(projectFile));
            if (!File.Exists(projectFile)) throw new FileNotFoundException("Python project missing.", projectFile);
            if (paths.Count == 0) return 0;

            var doc = new XmlDocument { PreserveWhitespace = true };
            doc.Load(projectFile);
            var root = doc.DocumentElement ?? throw new InvalidDataException("Project XML has no root element.");
            var nodes = root.GetElementsByTagName("SearchPath");
            XmlElement? node = nodes.Count > 0 ? nodes[0] as XmlElement : null;
            if (node == null)
            {
                var group = root.GetElementsByTagName("PropertyGroup").OfType<XmlElement>().FirstOrDefault();
                if (group == null)
                {
                    group = doc.CreateElement("PropertyGroup", root.NamespaceURI);
                    root.PrependChild(group);
                }
                node = doc.CreateElement("SearchPath", root.NamespaceURI);
                group.AppendChild(node);
            }
            var existing = node.InnerText.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(x => x.Trim()).ToList();
            int added = 0;
            foreach (var path in paths)
            {
                if (existing.Any(x => string.Equals(x, path, StringComparison.OrdinalIgnoreCase))) continue;
                existing.Add(path);
                added++;
            }
            if (added == 0) return 0;

            // PTVS can reload the .pyproj via Solution Explorer. Preserve the user's original first.
            File.Copy(projectFile, projectFile + ".rhino-bridge.bak", overwrite: true);
            node.InnerText = string.Join(";", existing);
            doc.Save(projectFile);
            return added;
        }
    }
}
